  const renderScreen = (quantity?: number) =>
    render(
      <ThemeContext.Provider value={mockTheme}>
        <MedicationDetailedScreen
          route={{
            params: {
              consultPlanId: 'plan-china',
              consultPolicyId: 'policy-china',
              currencyCode: 'HKD',
              drugName: 'Cozaar',
              id: 'drug-cozaar',
              pictures: { large: 'https://example.com/drug.png' },
              price: '239.2',
              quantity,
              subTitle: '50mg',
            },
          }}
        />
      </ThemeContext.Provider>,
    );

  test('defaults the quantity to 1 without adding it to the cart', async () => {
    const screen = renderScreen(4);

    await act(async () => {
      await Promise.resolve();
    });

    expect(screen.getByTestId('medication-quantity-value').props.children).toBe(1);

    fireEvent.press(screen.getByTestId('medication-consult-doctor'));

    expect(mockAddToCart).not.toHaveBeenCalled();
    expect(mockToastShow).not.toHaveBeenCalled();
    expect(mockNavigate).toHaveBeenCalledWith('ConsultSecondaryScreen', {
      bookingDrugs: [
        {
          productId: 'drug-cozaar',
          quantity: 1,
          price: 239.2,
          name: 'Cozaar',
          ingredients: [],
        },
      ],
      hideMedicationCategoryEntry: true,
      operatedPlan: expect.objectContaining({
        planId: 'plan-china',
        policyId: 'policy-china',
      }),
    });
  });

  test('asks for a quantity when the counter is cleared to zero', async () => {
    const screen = renderScreen();

    await act(async () => {
      await Promise.resolve();
    });

    fireEvent.press(screen.getByTestId('medication-quantity-decrease'));
    fireEvent.press(screen.getByTestId('medication-consult-doctor'));

    expect(mockNavigate).not.toHaveBeenCalled();
    expect(mockAddToCart).not.toHaveBeenCalled();
    expect(mockToastShow).toHaveBeenCalledWith(
      'please_select_drug_quantity',
      expect.objectContaining({ type: 'danger', placement: 'center' }),
    );
  });

  test('opens consult with only the current medication and its selected quantity', async () => {
    const screen = renderScreen();

    await act(async () => {
      await Promise.resolve();
    });

    fireEvent.press(screen.getByTestId('medication-quantity-increase'));
    fireEvent.press(screen.getByTestId('medication-consult-doctor'));

